patch.new:
def _binder_used(b, sent):
    # W16-R03-ADJ-01 patch: a composite binder (x,y,...) is used
    # iff every declared variable occurs as a standalone token in
    # the formal sentence. Literal tuple printing is not required
    # by rule_spec.json R03 ('a single sentence using those binders').
    if b in sent:
        return True
    if b.startswith("(") and b.endswith(")"):
        toks = [t.strip() for t in b[1:-1].split(",") if t.strip()]
        if toks and all(
            re.search(r"(?<![A-Za-z0-9_])" + re.escape(t) + r"(?![A-Za-z0-9_])", sent)
            for t in toks
        ):
            return True
    return False

for b in binders:
    if not _binder_used(b, formal):
        bad.append(f"binder {b!r} absent from formal sentence")

patch.old:
for b in binders:
    if b not in formal:
        bad.append(f"binder {b!r} absent from formal sentence")
